# Update lead status based on quotation status
if doc.lead and doc.status:
    lead_doc = frappe.get_doc("Lead Management", doc.lead)
    
    if doc.status == "Accepted":
        lead_doc.lead_status = "Hot Lead"
        frappe.msgprint("Quotation accepted! Lead marked as Hot Lead", indicator='green')
        
    elif doc.status == "Rejected":
        lead_doc.lead_status = "Lost"
        frappe.msgprint("Quotation rejected. Lead marked as Lost", indicator='red')
        
    elif doc.status == "Sent":
        lead_doc.lead_status = "Qualified"
    
    lead_doc.flags.ignore_permissions = True
    lead_doc.save()
